@OptIn(ExperimentalUnsignedTypes::class)
fun testUByte() {
    println("== UByteArray")
    val a = ubyteArrayOf(3u, 1u, 2u, 3u, 5u)
    val e0 = UByteArray(0)
    println(a.dropLastWhile { it > 2u })
    println(a.takeLastWhile { it > 2u })
    println(a.filterIndexedTo(ArrayList<UByte>()) { i, e -> i % 2 == 0 })
    println(a.filterNotTo(ArrayList<UByte>()) { it > 2u })
    val s = a.copyOf(); s.shuffle(kotlin.random.Random(42)); println(s.sorted())
    s.shuffle(); println(s.size)
    println(a.associateWithTo(LinkedHashMap<UByte, String>()) { "v" + it })
    println(a.flatMapIndexed { i, e -> listOf(i, e) })
    println(a.flatMapIndexedTo(ArrayList<Any>()) { i, e -> listOf(i, e) })
    println(a.flatMapTo(ArrayList<UByte>()) { listOf(it, it) })
    println(a.groupBy({ it.toString() }, { "x" + it }))
    println(a.groupByTo(LinkedHashMap<String, MutableList<UByte>>()) { it.toString() })
    println(a.groupByTo(LinkedHashMap<String, MutableList<String>>(), { it.toString() }, { "x" + it }))
    println(a.mapIndexedTo(ArrayList<String>()) { i, e -> i.toString() + e })
    println(a.foldRight("") { e, acc -> acc + e })
    println(a.foldRightIndexed("") { i, e, acc -> acc + e + i })
    println(a.maxBy { it.toInt() % 4 })
    println(a.minBy { it.toInt() % 4 })
    println(a.maxOfOrNull { it.toString() })
    println(a.minOfOrNull { it.toString() })
    println(e0.maxOfOrNull { it.toString() })
    println(a.maxOfWith(naturalOrder<String>()) { it.toString() })
    println(a.minOfWith(naturalOrder<String>()) { it.toString() })
    println(a.maxOfWithOrNull(naturalOrder<String>()) { it.toString() })
    println(a.minOfWithOrNull(naturalOrder<String>()) { it.toString() })
    println(e0.minOfWithOrNull(naturalOrder<String>()) { it.toString() })
    println(a.maxWith(compareBy<UByte> { it.toInt() % 4 }))
    println(a.minWith(compareBy<UByte> { it.toInt() % 4 }))
    println(a.maxWithOrNull(compareBy<UByte> { it.toInt() % 4 }))
    println(a.minWithOrNull(compareBy<UByte> { it.toInt() % 4 }))
    println(e0.maxWithOrNull(compareBy<UByte> { it.toInt() % 4 }))
    println(a.onEach { print(it) })
    println(a.onEachIndexed { i, e -> print(i.toString() + e) })
    println(a.reduceIndexedOrNull { i, acc, e -> (acc + e).toUByte() })
    println(e0.reduceIndexedOrNull { i, acc, e -> (acc + e).toUByte() })
    println(a.reduceRight { e, acc -> (acc + e).toUByte() })
    println(a.reduceRightIndexed { i, e, acc -> (acc + e).toUByte() })
    println(a.reduceRightIndexedOrNull { i, e, acc -> (acc + e).toUByte() })
    println(a.reduceRightOrNull { e, acc -> (acc + e).toUByte() })
    println(e0.reduceRightOrNull { e, acc -> (acc + e).toUByte() })
    println(a.runningFold("") { acc, e -> acc + e })
    println(a.runningFoldIndexed("") { i, acc, e -> acc + e + i })
    println(a.runningReduce { acc, e -> (acc + e).toUByte() })
    println(a.runningReduceIndexed { i, acc, e -> (acc + e).toUByte() })
    println(a.scan("") { acc, e -> acc + e })
    println(a.scanIndexed("") { i, acc, e -> acc + e + i })
    println(a.sumBy { it.toUInt() })
    println(a.sumByDouble { it.toInt() * 0.5 })
    println(a.sumOf { it.toInt() })
    println(a.sumOf { it.toLong() })
    println(a.sumOf { it.toUInt() })
    println(a.sumOf { it.toULong() })
    println(a.sumOf { it.toInt() * 0.5 })
}

